fn is_nested(string: str) -> bool:
    """
    Create a function that takes a string as input which contains only square brackets.
    The function should return True if and only if there is a valid subsequence of brackets 
    where at least one bracket in the subsequence is nested.
    """
    var states: {(int, int)} = set()
    states.add((0, 0))

    for char in string:
        var new_states: {(int, int)} = set()
        for state in states:
            open_count, max_depth = state

            # Skip this character
            new_states.add((open_count, max_depth))

            if char == '[':
                # Include this opening bracket
                var new_open = open_count + 1
                var new_max = max(max_depth, new_open)
                new_states.add((new_open, new_max))
            elif char == ']' and open_count > 0:
                # Include this closing bracket
                var new_open = open_count - 1
                new_states.add((new_open, max_depth))

        states = new_states

    # Check if we reached a state with open_count=0 and max_depth>=2
    for state in states:
        open_count, max_depth = state
        if open_count == 0 and max_depth >= 2:
            return True

    return False
