        return 0

    # inc[i] = max sum of increasing subsequence ending at i
    var inc: [int] = []
    for i in range(n):
        inc.append(arr[i])

    # Calculate increasing subsequences
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i] = max sum of decreasing subsequence starting at i
    var dec: [int] = []
    for i in range(n):
        dec.append(arr[i])

    # Calculate decreasing subsequences (go from right to left)
    var i = n - 2
    while i >= 0:
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], arr[i] + dec[j])
        i -= 1

    # Find maximum bitonic sum
    var result = arr[0]
    for i in range(n):
        result = max(result, inc[i] + dec[i] - arr[i])

    return result
