fn helper(n: int, inout memo: {int: int}) -> int:
    if n in memo:
        return memo[n]

    if n == 0:
        return 0

    sum_val = helper(n // 2, &memo) + helper(n // 3, &memo) + helper(n // 4, &memo) + helper(n // 5, &memo)
    result = sum_val if sum_val > n else n
    memo[n] = result
    return result
